local function GetFirstZone(value)
    if type(value) ~= "table" then
        return value
    end

    if value[1] then
        return value[1]
    end

    for zoneKey, zone in pairs(value) do
        if type(zone) == "boolean" then
            if zone then
                return zoneKey
            end
        else
            return zone
        end
    end
